PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE tags (     id INTEGER PRIMARY KEY AUTOINCREMENT,     codigo TEXT NOT NULL UNIQUE,     ativada INTEGER NOT NULL DEFAULT 0,     bloqueada INTEGER NOT NULL DEFAULT 0,     data_criacao TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,     data_ativacao TEXT );
CREATE TABLE pets (     id INTEGER PRIMARY KEY AUTOINCREMENT,     tag_codigo TEXT NOT NULL UNIQUE,     nome TEXT NOT NULL,     especie TEXT NOT NULL,     raca TEXT,     sexo TEXT,     idade TEXT,     comportamento TEXT,     nome_tutor TEXT NOT NULL,     whatsapp TEXT NOT NULL,     cidade TEXT NOT NULL,     status TEXT NOT NULL DEFAULT 'seguro',     foto_url TEXT,     data_cadastro TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, cep TEXT, logradouro TEXT, bairro TEXT, estado TEXT, numero TEXT, complemento TEXT, perdido INTEGER DEFAULT 0, email TEXT,     FOREIGN KEY (tag_codigo) REFERENCES tags(codigo) );
CREATE TABLE leituras (id INTEGER PRIMARY KEY AUTOINCREMENT, tag_codigo TEXT NOT NULL, data_hora TEXT NOT NULL, ip TEXT, user_agent TEXT, pais TEXT, estado TEXT, cidade TEXT);
CREATE TABLE codigos_login (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL, codigo_hash TEXT NOT NULL, criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, expira_em TEXT NOT NULL, usado INTEGER NOT NULL DEFAULT 0, tentativas INTEGER NOT NULL DEFAULT 0, ip TEXT);
CREATE TABLE sessoes_tutor (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, criado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, expira_em TEXT NOT NULL, ultimo_acesso TEXT, ip TEXT, user_agent TEXT);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_codigos_login_email ON codigos_login(email);
CREATE INDEX idx_sessoes_tutor_token ON sessoes_tutor(token_hash);
CREATE INDEX idx_pets_email ON pets(email);
